def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    original_caps = bins + np.where(bins == np.max(bins), 0, 0) # proxy for bin capacity structure
    fill_ratio = item / (bins + 1e-7)
    scores = np.where(valid, 1.0 / (1.0 + np.abs(rem - fill_ratio)), -np.inf)
    return scores
